window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II and wenn-sentences · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"If I were you, I would …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"Eva's reality – Eva's wishes. Fill in: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"She would like to be taller, though.","why":"*grösser sein*: the wish form of *sein* is **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"She would like to speak Spanish well, though.","why":"An infinitive stands at the end (*sprechen*), so the wish is **würde** + infinitive.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"She would rather work as a tour guide, though.","why":"Infinitive at the end (*arbeiten*) → **würde** + infinitive. *lieber* = rather.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"She would like to have a big flat, though.","why":"*eine Wohnung haben*: the wish form of *haben* is **hätte**. No infinitive is needed.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"What are the people thinking?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Match each picture with a phrase from the box.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"If I didn't have to work, I would be sitting in the garden now.","why":"Picture 1 shows him working, then dreaming in a deck chair. After a *wenn*-clause the main clause starts with the verb (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"If I had a car, I wouldn't have to cycle in the rain.","why":"He is cycling in the rain; a car would spare him that. *müsste* is the Konjunktiv II of *müssen*. *Velo* is Swiss for *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"If the bus weren't late, I would be at the office on time.","why":"A late bus makes her late for work. *wäre* is the Konjunktiv II of *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Rewrite the sentences from a: start with the main clause, then the wenn-clause.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"I wouldn't have to cycle in the rain if I had a car.","why":"Main clause first, then the *wenn*-clause. In the *wenn*-clause the verb (*hätte*) goes to the end.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"I would be at the office on time if the bus weren't late.","why":"Same pattern: main clause, comma, *wenn* … verb at the end (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Fill in the words from the box. Each word is used once; the crossed-out ones are used in the example.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"I would do some things differently if I were the boss in our company.","why":"*machen* at the end → **würde** + infinitive. *Chefin sein* → **wäre**, at the end of the *wenn*-clause.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"If I were Marco, I would definitely do vocational training.","why":"*Marco sein* → **wäre** (like *Wenn ich du wäre …*). The main clause has the infinitive *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"If I could decide freely, I would work in a small company.","why":"*frei entscheiden können* → **könnte** at the end of the *wenn*-clause. Main clause with *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"If we had children, I would only have to work half days.","why":"*Kinder haben* with *wir* → **hätten**. The box leaves **müsste** for the last gap.","source":"k2","check":"*müsste* and *würde* are both correct German in b, c and e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* is just as good). The box only says which three gaps get *würde* and which one gets *müsste*; this key is the most likely split. Ask your teacher which one the book wants."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"I have to hurry because of my work.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Rewrite the answers with weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Because my girlfriend is unpunctual.","why":"*wegen* + noun becomes *weil* + a clause with a verb; the verb (*ist*) goes to the end.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Because the weather is bad.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; after *weil* the verb goes to the end.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Because I have an important appointment.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusative after *haben*); verb at the end.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Fill in: wegen – weshalb – weil – deswegen – denn. A word can be used more than once.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"I can only understand him badly because of his pronunciation.","why":"A noun follows (*seiner Aussprache*, genitive), not a clause → the preposition **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Someday I'd like to travel to Italy, because I'd like to see the sea.","why":"The verb stays in 2nd place after the gap (*ich möchte*) → **denn**. With *weil* it would go to the end.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"I need to improve my listening, so I watch a lot of films.","why":"The second part is the consequence, and the verb comes right after the gap (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"My children learned German quickly because they are always with Swiss children at kindergarten.","why":"The verb is at the end (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Why do you write the words on little cards?","why":"A question word is needed: **Weshalb** means *warum* (why)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"My sister already speaks almost fluent German, so she can help me learn German.","why":"Consequence, and the verb comes right after the gap (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"At the language course. Fill in: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"I couldn't do the last exercise because I didn't understand it.","why":"The verb is at the end (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"There was nobody at registration, so I went back home.","why":"A new sentence that gives the consequence, with the verb right after the gap (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Because of my good marks, I didn't have to take a test at the start of the course.","why":"A noun phrase follows (*meiner guten Noten*, genitive plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"There is an extra language course because a lot of people have signed up.","why":"The verb is at the end (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Unfortunately I couldn't come to the course yesterday because of my toothache.","why":"A noun phrase follows (*meiner Zahnschmerzen*, genitive plural) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Who can find the best excuses? Choose one situation and write. The model answers are only one possibility each.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Unfortunately I couldn't tidy the kitchen, because I suddenly had bad back pain. I had to lie down. That's why I watched a film.","why":"Uses *weil* (verb at the end: *hatte*) and *Deswegen* (verb right after it: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Because of the flu, I didn't go to the final exam. I had a high temperature, so I stayed in bed.","why":"Uses *wegen* + genitive (*einer Grippe*) and *deswegen* + verb (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"I'm so sorry! Unfortunately I'm late, because there was an accident on the motorway. Because of the traffic jam I lost two hours.","why":"*denn* keeps the verb in 2nd place (*war*). *wegen des Staus*: genitive of *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (if-sentences, including unreal ones with Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis connector dictionary: wenn (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis connector dictionary: weil (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis connector dictionary: denn (causal, verb stays in 2nd place)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis connector dictionary: deswegen (consequence; stands before the verb or in the middle)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen with genitive)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Growing up with several languages · reading, forum post, crossword, favourite words","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"At home in several languages","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Two or three languages in one family – no problem?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Who says what? Read the three texts and write the name of the person who says each sentence.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“Children want to speak the same language as their friends.” – Janusz","why":"Janusz (text B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“It's good to speak several languages very well, isn't it?” – Yara","why":"Yara (text C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“My children switch between two languages.” – Amira","why":"Amira (text A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* She is the only one who talks about her own children."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"What is right? Read the texts again. Type *richtig* (right) or *falsch* (wrong) after each sentence; in the book you tick only the right ones.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Amira's children speak Arabic better than German. → right","why":"The family always speaks Arabic at home: *Darum können das die Kinder viel besser.* (Their German here is Swiss German.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"In Amira's family only German is spoken. → wrong","why":"The opposite: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz learned German for six years. → wrong","why":"He was six years old when the family moved (*als ich sechs Jahre alt war*), and he spoke fluent High German after one year."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz and his sister didn't want to speak Polish with their parents. → right","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara speaks three languages fluently. → right","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* German is her fourth language, and she doesn't speak it well yet."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara will soon learn German too. → wrong","why":"She isn't starting soon (*bald*): she has been learning German for two years already (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"At home in several languages","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Writing a forum post. You watched a TV debate on growing up with several languages. In the programme's online forum you find this opinion:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Make notes on the four questions. Short notes are enough, no full sentences. The model notes are one possibility.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Yes: my neighbour's son – Italian with his mother, Swiss German at school","why":"Notes only: a name or person, and which languages where."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"learning two languages without a course, contact with family abroad, advantages at work","why":"Collect two or three advantages; you need them for *Ich finde es sehr gut, dass …* in b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mixing the languages, one language is weaker, a lot of work for the parents","why":"These go into *Es könnte schwierig sein, dass …* and *Auf der anderen Seite …* in b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"no – children learn two languages well if their parents talk to them a lot","why":"Decide yes or no and give one reason: that becomes *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Now write your opinion on the topic (about 80 words). Use your notes from a and some of the phrases.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"I don't agree with Sandra, because many children learn two languages without problems. My neighbour's son is growing up with Italian and German. He speaks Italian with his mother and Swiss German at school. I think it's very good that he is learning two languages so early. It could be difficult that he sometimes mixes the languages. On the other hand, that is normal for small children. Most important of all is that the parents talk to the child a lot. That's why each parent should speak their own language.","why":"About 85 words, using six of the phrases. *denn* keeps the verb in 2nd place (*lernen*); after *Deswegen* the verb comes next (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Solve the crossword. Each sentence gives the first letter of the missing word. The grid isn't shown here: type the whole word. In the book's grid Ä fills one box.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Our home country is Spain. We come from Spain.","why":"*aus einem Land stammen* = to come from a country (like *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda and Mike don't see each other for six months. That's a long separation.","why":"*die Trennung* = separation, the noun of *sich trennen*. *eine lange* → a feminine noun."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"German and Arabic don't have the same script.","why":"*die Schrift* = script, the letters a language is written in. Arabic uses a different alphabet."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter lives in America now. Since he has lived there, he has changed a lot.","why":"*sich verändern* = to change (as a person). Perfekt: *hat sich verändert*. The Ä fills one box."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"She writes books. She is an author by profession.","why":"*Sie* → the female form with *-in*: *der Autor → die Autorin*. No article after *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"The children don't do their homework. That's why their parents tell them off.","why":"*mit jemandem schimpfen* = to tell someone off. Plural subject *die Eltern* → *schimpfen*. After *Deshalb* the verb comes next."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"She has only been working for a few months. She still has little experience in her job.","why":"*die Erfahrung* = experience. *wenig Erfahrung haben* = to have little experience."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Now we have chaos. Everything is in a mess.","why":"*durcheinander sein* = to be in a mess, mixed up. Written as one word."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"For Ye-Jon the sounds P and F sound the same. She can't tell them apart.","why":"*unterscheiden* = to tell apart. With *kann* the infinitive goes to the end. *tönen* is Swiss for *klingen* (to sound)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"I'm travelling to Greece in the holidays, but unfortunately I can't speak any Greek.","why":"*Griechisch* = the Greek language, with a capital letter. *kein Griechisch können* = not to speak any Greek."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"He only eats vegetables and rice. He eats exclusively vegetables and rice.","why":"*ausschliesslich* = exclusively, nothing but. Swiss spelling with *ss*; Germany writes it with the sharp s."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Solution word (the highlighted row in the grid): mother tongue","why":"Each word gives one letter of the highlighted row: stam**M**en, trenn**U**ng, schrif**T**, (T in the grid), veränd**E**rt, auto**R**in, (S in the grid), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"At home in several languages","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"My most beautiful German word","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Match each photo with a word from the box. The book's coloured dots give the article: blue = der, green = das, red = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (a caramel custard dessert)","why":"Swiss name for crème caramel. *Chöpfli* is Swiss German for 'little head' (*Kopf*). Green dot → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – shooting star","why":"*der Stern* = star; *die Sternschnuppe* = shooting star. Red dot → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – butterfly","why":"Swiss word for *der Schmetterling* (butterfly); Duden marks it *schweizerisch, sonst landschaftlich*. Blue dot → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Why might someone find exactly these words the most beautiful? What do you think? Make notes, then talk about them. The model notes are one possibility.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"so colourful and light, reminds you of summer, funny: the animal isn't a bird at all","why":"Think of what the word makes you see or feel, and how it sounds."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"sweet, reminds you of childhood, sounds funny and typically Swiss","why":"*tönen* = Swiss for *klingen* (to sound)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantic, you can make a wish, sounds soft","why":"Short notes are enough: adjectives and a reason."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"My favourite word","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Which German word and which word in your mother tongue do you like? Why? Write a short text, using the phrases. The model answer is one possibility.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"My favourite German word is “gemütlich” (cosy). When I hear this word, I think of a winter evening with tea, candles and friends. That's why I find it so nice. It sounds soft and warm. In my mother tongue, English, there is no word with exactly this meaning. In English I like the word “sunshine”. For me it is a happy word, because it sounds bright and friendly.","why":"*Wenn …, dann* + verb next (*denke ich*); *Deshalb* + verb next (*finde ich*). Swap in your own mother tongue and words.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Present your text in class. A possible way to start is shown in the model.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Today I'd like to present my favourite word to you. It's the word “gemütlich”. …","why":"Start by naming the word, then read your text from a. *euch* for classmates, *Ihnen* if you speak formally."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis connector dictionary: deswegen (consequence; stands before the verb or in the middle)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis connector dictionary: wenn (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]}];
